import csv
import io
import re


def parse_csv(raw_csv: str):
    expected_width = 13
    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        strict=False,
    )

    parsed_rows = []
    for row in reader:
        if not row or all(value == "" for value in row):
            continue
        parsed_rows.append(row)

    if not parsed_rows:
        return {"columns": [], "rows": []}

    parsed_rows[0][0] = parsed_rows[0][0].lstrip("\ufeff")

    header_index = None
    for index, row in enumerate(parsed_rows):
        if len(row) != expected_width:
            continue
        label_count = sum(bool(re.search(r"[A-Za-z_]", value)) for value in row)
        numeric_count = sum(
            bool(re.fullmatch(r"\s*[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?\s*", value))
            for value in row
        )
        if label_count >= 2 and numeric_count < len(row) // 2:
            header_index = index
            break

    if header_index is None:
        header_index = 0

    columns = list(parsed_rows[header_index])
    data_rows = parsed_rows[header_index + 1:]
    width = max(expected_width, len(columns))
    if data_rows:
        width = max(width, max(len(row) for row in data_rows))

    while len(columns) < width:
        columns.append("column_" + str(len(columns) + 1))

    rows = []
    for row in data_rows:
        normalized = list(row[:width])
        normalized.extend([""] * (width - len(normalized)))
        rows.append(normalized)

    return {"columns": columns, "rows": rows}
